import './Login.css';
import axios from 'axios';
import NavigationBar from './NavigationBar';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import { useEffect, useState } from 'react';

function Admin() {

    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);  // Add loading state
    const [error, setError] = useState(null);      // Add error state

    useEffect(() => {
        loadUsers();
    }, []);

    const loadUsers = async () => {
        try {
        const response = await api.get("/api/admin/users"); // ✅ Uses api instance with JWT
        setUsers(response.data);
        setLoading(false);
        } catch (error) {
        console.error("Error fetching users:", error);
        setError("Failed to load users. Check if you have admin access.");
        setLoading(false);
        }
    };
    
    return(
        <div fluid>
            <Container style={{width:"100%", paddingTop:"1.5rem"}}>
                <Row>
                    <Col style={{paddingBottom:"1.5rem"}}>
                        <h1>Admin</h1>
                    </Col>
                </Row>
                <Row>
                    <Col>
                    <table className="table border shadow">
                        <thead>
                            <tr>
                            <th scope="col">#</th>
                            <th scope="col">Email</th>
                            <th scope="col">Username</th>
                            <th scope="col">Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            {
                                users.map((user,index)=>(
                                    <tr>
                                    <th scope="row" key={index}>{index + 1}</th>
                                    <td>{user.email}</td>
                                    <td>{user.username}</td>
                                    </tr>
                                ))
                            }
                        </tbody>
                    </table>
                    </Col>
                </Row>
            </Container>
        </div>
    )
}

export default Admin;
